    "inlineSchema": "generator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// 操作区分\nenum TonerAction {\n  REGISTER // 登録（マスタ新規追加）\n  RECEIVE // 搬入（在庫加算）\n  ISSUE // 持ち出し（在庫減算）\n  DISPOSE // 廃棄（搬入累計の範囲内でのみ記録）\n\n  @@map(\"toner_action\")\n}\n\n/// SNMP のバージョン。機種によって片方しか応答しない\nenum SnmpVersion {\n  V1  @map(\"1\")\n  V2C @map(\"2c\")\n\n  @@map(\"snmp_version\")\n}\n\n/// 注文の状態\nenum OrderStatus {\n  PENDING // 発注済み・未入荷\n  RECEIVED // 入荷済み\n  CANCELED // 取消\n\n  @@map(\"order_status\")\n}\n\n/// トナーマスタ\nmodel Toner {\n  id        String   @id\n  name      String?\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  stock   TonerStock?\n  entries TonerEntry[]\n  orders  TonerOrder[]\n\n  @@map(\"toners\")\n}\n\n/// 在庫テーブル（品番ごとの現在数と累計）\nmodel TonerStock {\n  tonerId String @id @map(\"toner_id\")\n\n  /// 現在庫。搬入で増え、持ち出しで減る\n  quantity Int @default(0)\n\n  /// 搬入の累計。廃棄できる本数の上限になる\n  received Int @default(0)\n\n  /// 廃棄の累計。received を超えられない\n  disposed Int @default(0)\n\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  toner Toner @relation(fields: [tonerId], references: [id], onDelete: Cascade)\n\n  @@map(\"toner_stocks\")\n}\n\n/// 履歴テーブル（誰がいつ何をしたか）\nmodel TonerEntry {\n  id      Int         @id @default(autoincrement())\n  userId  String      @map(\"user_id\")\n  tonerId String      @map(\"toner_id\")\n  action  TonerAction\n\n  /// 操作した本数。常に 0 以上。登録は 0\n  quantity Int @default(0)\n\n  /// 操作直後の在庫数\n  balance Int @default(0)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  toner Toner @relation(fields: [tonerId], references: [id])\n\n  @@index([createdAt])\n  @@index([tonerId, createdAt])\n  @@map(\"toner_entries\")\n}\n\n/// 注文テーブル\nmodel TonerOrder {\n  id      Int    @id @default(autoincrement())\n  tonerId String @map(\"toner_id\")\n\n  /// 注文した本数\n  quantity Int\n\n  /// 注文日時。入力値を保持する（登録日時とは別）\n  orderedAt DateTime @map(\"ordered_at\")\n\n  status OrderStatus @default(PENDING)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  toner Toner @relation(fields: [tonerId], references: [id])\n\n  @@index([status, orderedAt])\n  @@index([tonerId, orderedAt])\n  @@map(\"toner_orders\")\n}\n\n/// プリンター。IP アドレスで一意に管理する\nmodel Printer {\n  id Int @id @default(autoincrement())\n\n  /// SNMP の宛先。登録の入力値\n  ipAddress String @unique @map(\"ip_address\")\n\n  /// SNMP コミュニティ名\n  community String @default(\"public\")\n\n  /// 応答があったバージョン。次回のポーリングで最初に試す\n  version SnmpVersion @default(V1)\n\n  /// sysName（1.3.6.1.2.1.1.5.0）\n  hostName String? @map(\"host_name\")\n\n  /// hrDeviceDescr ないし sysDescr から拾った機種名\n  model String?\n\n  serialNumber String? @map(\"serial_number\")\n  macAddress   String? @map(\"mac_address\")\n\n  /// 設置場所。SNMP の sysLocation ではなく手入力を優先する\n  location String?\n\n  /// 累計印刷枚数（prtMarkerLifeCount）\n  pageCount Int? @map(\"page_count\")\n\n  /// 直近のポーリングで応答があったか\n  reachable Boolean @default(false)\n\n  /// 応答がなかったときの理由\n  lastError String? @map(\"last_error\")\n\n  lastPolledAt DateTime? @map(\"last_polled_at\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  readings SupplyReading[]\n  pageDays PageCountDaily[]\n\n  @@map(\"printers\")\n}\n\n/// 日次の印刷枚数。累計カウンタのスナップショットと、そこから出した 1 日分\nmodel PageCountDaily {\n  id        Int @id @default(autoincrement())\n  printerId Int @map(\"printer_id\")\n\n  /// 集計対象日。この日に印刷された枚数を pages に持つ\n  date DateTime @db.Date\n\n  /// date の終了時点で読んだ累計印刷枚数（prtMarkerLifeCount）\n  total Int\n\n  /// date 当日の印刷枚数。前回値がない初回と、\n  /// カウンタが巻き戻った（機器交換・リセット）ときは null\n  pages Int?\n\n  /// pages が何日分か。1 なら純粋に date 当日の分。\n  /// 取得が飛ぶと 2 以上になり、その日数分をまとめた値になる\n  spanDays Int @default(1) @map(\"span_days\")\n\n  /// 実際に SNMP を読んだ時刻\n  capturedAt DateTime @default(now()) @map(\"captured_at\")\n\n  printer Printer @relation(fields: [printerId], references: [id], onDelete: Cascade)\n\n  @@unique([printerId, date])\n  @@index([date])\n  @@map(\"page_count_daily\")\n}\n\n/// トナー等の残量。ポーリングのたびに上書きする\nmodel SupplyReading {\n  id        Int @id @default(autoincrement())\n  printerId Int @map(\"printer_id\")\n\n  /// prtMarkerSuppliesTable の行番号\n  supplyIndex Int @map(\"supply_index\")\n\n  /// prtMarkerSuppliesDescription\n  name String\n\n  /// 色名（prtMarkerColorantValue）。黒一色の機種では null\n  colorant String?\n\n  /// 残量。-1 = 不明、-2 = 取得不可、-3 = 残量あり（数値では取れない）\n  level Int\n\n  /// 満量時の値。-1 / -2 は不明\n  maxCapacity Int @map(\"max_capacity\")\n\n  /// level と maxCapacity から出したパーセント。出せないときは null\n  percent Int?\n\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  printer Printer @relation(fields: [printerId], references: [id], onDelete: Cascade)\n\n  @@unique([printerId, supplyIndex])\n  @@map(\"supply_readings\")\n}\n",
